let mySettings=null,photoDraft=null;
async function openMySettings(){try{mySettings=await api('settings-load');drawMySettings();}catch(e){toast(e.message);}}
function drawMySettings(){const d=mySettings,p=d.profile||{},jobs=(d.jobs||[]).filter(j=>j.active||j.id===p.job_title_id);show(`<h2>Minhas configurações</h2><p>Seus dados pessoais e de acesso.</p>${!d.ready?'<div class="notice">O cadastro pessoal aguarda a execução do SQL de configurações no Supabase. A alteração de senha já está disponível.</div>':''}<div class="settings-layout"><section class="settings-details"><form><div class="formgrid">${field('full_name','Nome completo',p.full_name||user().name,'text','required maxlength="180"')}${field('cpf','CPF',p.cpf||'','text','maxlength="14" inputmode="numeric"')}${field('contact_email','E-mail de contato',p.contact_email||'','email','maxlength="254"')}${field('phone','Telefone / WhatsApp',p.phone||'','tel','maxlength="30"')}${select('job_title_id','Cargo',[['','Não informado'],...jobs.map(j=>[j.id,j.name+(j.active?'':' (inativo)')])],p.job_title_id||'')}</div><h3>Dados para recebimento</h3><div class="formgrid">${[['bank_name','Banco'],['bank_agency','Agência'],['bank_account','Conta com dígito'],['bank_holder','Titular da conta'],['pix_key','Chave Pix']].map(([key,label])=>field(key,label,p[key]||'','text','maxlength="180"')).join('')}</div><p class="small">O cargo descreve sua função. As empresas e permissões são definidas pelo administrador.</p>${d.ready?actions():''}</form></section><section class="settings-account"><h3>Foto de perfil</h3><img id="profilePhoto" src="${esc(d.photo||'')}" alt="Sua foto" ${d.photo?'':'hidden'} class="profile-photo"><p class="small photo-intro">JPG ou PNG · até 2 MB. Recomendado: imagem quadrada de pelo menos 512 × 512 px. O recorte será salvo em 512 × 512 px.</p>${d.ready?'<label class="photo-select">Selecionar foto<input type="file" id="photoInput" accept="image/jpeg,image/png" onchange="prepareMyPhoto(this.files[0])"></label><div id="photoEditor" hidden><h3>Recortar foto</h3><canvas id="photoCanvas" width="512" height="512" aria-label="Prévia do recorte da foto"></canvas><label>Zoom<input id="photoZoom" type="range" min="1" max="3" value="1" step="0.01" oninput="paintPhotoCrop()"></label><label>Posição horizontal<input id="photoX" type="range" min="0" max="100" value="50" oninput="paintPhotoCrop()"></label><label>Posição vertical<input id="photoY" type="range" min="0" max="100" value="50" oninput="paintPhotoCrop()"></label><p id="photoDimensions" class="small"></p><div class="actions"><button type="button" class="btn secondary" onclick="cancelPhotoCrop()">Cancelar recorte</button><button type="button" class="btn" id="savePhoto" onclick="saveMyPhoto()">Salvar e confirmar foto</button></div></div><p id="photoFeedback" role="status" aria-live="polite"></p>':''}<div class="settings-access"><h3>Acesso</h3><p>E-mail de acesso: <strong>${esc(d.loginEmail||user().email)}</strong></p><p class="small">O e-mail de contato não altera o login. Para trocar o e-mail de acesso, solicite ao administrador.</p><div class="actions">${isAdmin()?btn('Gerenciar cargos','openJobSettings()',true):''}${btn('Alterar senha','openPasswordSettings()',true)}${btn('Fechar',"document.getElementById('modal').close()",true)}</div></div></section></div>`,async f=>{if(!d.ready)throw Error('Execute o SQL de configurações primeiro.');await api('settings-save',{profile:Object.fromEntries(['full_name','cpf','contact_email','phone','job_title_id','bank_name','bank_agency','bank_account','bank_holder','pix_key'].map(k=>[k,f.get(k)||'']))});const savedPage=page,savedCompany=company;await loadCloud();page=savedPage;company=savedCompany;render();await openMySettings();toast('Dados pessoais atualizados.');});document.getElementById('modal').classList.add('settings-modal');}
async function prepareMyPhoto(file){if(!file)return;try{if(!['image/jpeg','image/png'].includes(file.type)||file.size>2097152||!file.size)throw Error('Envie JPG ou PNG de até 2 MB.');const image=await createImageBitmap(file);if(photoDraft?.image)photoDraft.image.close();photoDraft={image};document.getElementById('photoEditor').hidden=false;document.getElementById('photoZoom').value=1;document.getElementById('photoX').value=50;document.getElementById('photoY').value=50;document.getElementById('photoDimensions').textContent=`Original: ${image.width} × ${image.height} px · ${(file.size/1024).toFixed(0)} KB. Ajuste o recorte e confirme para salvar.`;document.getElementById('photoFeedback').textContent='Foto selecionada. Ainda não foi salva.';paintPhotoCrop();}catch(e){toast(e.message);}}
function photoCropRect(width,height,zoom,x,y){const side=Math.min(width,height)/Math.max(1,Math.min(3,zoom));return {side,x:(width-side)*Math.max(0,Math.min(100,x))/100,y:(height-side)*Math.max(0,Math.min(100,y))/100};}
function paintPhotoCrop(){if(!photoDraft)return;const image=photoDraft.image,rect=photoCropRect(image.width,image.height,Number(document.getElementById('photoZoom').value),Number(document.getElementById('photoX').value),Number(document.getElementById('photoY').value));const canvas=document.getElementById('photoCanvas'),context=canvas.getContext('2d');context.clearRect(0,0,512,512);context.drawImage(image,rect.x,rect.y,rect.side,rect.side,0,0,512,512);}
function cancelPhotoCrop(){if(photoDraft?.saving)return;if(photoDraft?.image)photoDraft.image.close();photoDraft=null;document.getElementById('photoEditor').hidden=true;document.getElementById('photoInput').value='';document.getElementById('photoFeedback').textContent='Recorte cancelado. Sua foto foi mantida.';}
async function saveMyPhoto(){if(!photoDraft||photoDraft.saving)return;const draft=photoDraft,button=document.getElementById('savePhoto'),feedback=document.getElementById('photoFeedback');draft.saving=true;const modal=document.getElementById('modal'),lockedButtons=Array.from(modal.querySelectorAll('button'));const preventClose=e=>e.preventDefault();modal.addEventListener('cancel',preventClose);lockedButtons.forEach(b=>b.disabled=true);button.disabled=true;document.getElementById('photoInput').disabled=true;try{const file=await new Promise(resolve=>document.getElementById('photoCanvas').toBlob(resolve,'image/jpeg',0.9));if(!file)throw Error('Não foi possível preparar a foto.');feedback.textContent='Salvando foto…';const upload=await api('photo-begin',{contentType:file.type,size:file.size});const response=await fetch(upload.url,{method:'PUT',headers:{'Content-Type':file.type,'x-upsert':'false'},body:file});if(!response.ok)throw Error('Não foi possível enviar a foto. Tente novamente.');await api('photo-finish');const refreshed=await api('settings-load');mySettings.photo=refreshed.photo;const image=document.getElementById('profilePhoto');image.src=refreshed.photo;image.hidden=false;draft.saving=false;cancelPhotoCrop();feedback.textContent='Foto salva e confirmada.';}catch(e){feedback.textContent=e.message;}finally{draft.saving=false;modal.removeEventListener('cancel',preventClose);lockedButtons.forEach(b=>b.disabled=false);document.getElementById('photoInput').disabled=false;}}
async function openJobSettings(){if(!isAdmin())return;try{const d=await api('settings-load');if(!d.ready)return toast('Execute o SQL de configurações primeiro.');show(`<h2>Cargos da equipe</h2><p>Disponíveis para seleção nas configurações pessoais.</p><ul>${d.jobs.map(j=>`<li style="margin:12px 0">${esc(j.name)} · ${j.active?'Ativo':'Inativo'} ${btn(j.active?'Desativar':'Ativar',`toggleJob('${actionId(j.id)}',${!j.active})`,true)}</li>`).join('')||'<li>Nenhum cargo cadastrado.</li>'}</ul><form>${field('name','Novo cargo','','text','required minlength="2" maxlength="100"')}${actions()}</form>`,async f=>{await api('job-save',{name:f.get('name')});await openJobSettings();});}catch(e){toast(e.message);}}
async function toggleJob(id,active){const job=mySettings?.jobs?.find(j=>j.id===id);try{const d=await api('settings-load'),j=d.jobs.find(j=>j.id===id);if(!j)throw Error('Cargo não encontrado.');await api('job-save',{id,name:j.name,active});await openJobSettings();}catch(e){toast(e.message);}}
function openPasswordSettings(){show(`<h2>Alterar senha</h2><form>${field('currentPassword','Senha atual','','password','required autocomplete="current-password"')}${field('newPassword','Nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('confirmPassword','Confirmar nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="small">Use pelo menos 12 caracteres. A senha é enviada somente ao serviço de autenticação.</p>${actions()}</form>`,async f=>{const password=f.get('newPassword');if(password!==f.get('confirmPassword'))throw Error('As senhas não coincidem.');const session=await authRequest('token?grant_type=password',{email:mySettings?.loginEmail||user().email,password:f.get('currentPassword')});const response=await fetch(CLOUD_URL+'/auth/v1/user',{method:'PUT',headers:{apikey:CLOUD_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({password})});const result=await response.json();if(!response.ok)throw Error(result.msg||result.message||'Não foi possível alterar a senha.');cloudSession=session;localStorage.setItem('comissions-auth-session',JSON.stringify(session));document.getElementById('modal').close();toast('Senha alterada.');});}
